package com.tripmateai.mapper; import com.tripmateai.dto.response.packing.*; import com.tripmateai.entity.*; import java.util.*; public final class PackingMapper {private PackingMapper(){} public static PackingItemResponse item(PackingItem i){return new PackingItemResponse(i.getId(),i.getName(),i.getQuantity(),i.getCategory(),i.isPacked());} public static PackingChecklistResponse checklist(PackingChecklist c,List<PackingItem> items){return new PackingChecklistResponse(c.getId(),c.getName(),items.stream().map(PackingMapper::item).toList());}}
